Assume that a burst erasure spans time indices ${j-B, \ldots, j-1}$. The decoder must recover 
\begin{equation}
\label{eq:decoder1}
{\hat{\mathssf{s}}}_{j+1}^n = {\mathcal{G}}_{j+1}\left([{\mathssf{f}}]_0^{j-B-1}, {\mathssf{f}}_{j}, {\mathssf{f}}_{j+1}, {\mathssf{s}}_{-1}^n\right).
\end{equation} 






Furthermore if there is no erasure until time $j$ then \begin{align}\hat{{\mathssf{s}}}_j^n = {\mathcal{G}}_j\left([{\mathssf{f}}]_0^{j}, {\mathssf{s}}_{-1}^n\right)\label{eq:decoder0}\end{align} must hold. 





Our aim is to

\label{lem:memoryless}
For the class of memoryless encoding functions, i.e. ${\mathssf{f}}_j = {\mathcal{F}}_j({\mathssf{s}}_j^n)$, 

the decoding functions 

$\hat{{\mathssf{s}}}_j^n = {{\mathcal{G}}}_{j}([{\mathssf{f}}]_0^j,{\mathssf{s}}_{-1}^n)$ and $\hat{{\mathssf{s}}}_{j+1}^n = {{\mathcal{G}}}_{j+1}([{\mathssf{f}}]_0^{j-2}, {\mathssf{f}}_j, {\mathssf{f}}_{j+1},{\mathssf{s}}_{-1}^n)$





can be replaced by the following decoding functions
\begin{align}
&\tilde{{\mathssf{s}}}_j^n = \tilde{{\mathcal{G}}}_{j}({\mathssf{f}}_j,{\mathssf{s}}_{j-1}^n) \label{eq:Fano2a}\\
&\tilde{{\mathssf{s}}}_{j+1}^n = \tilde{{\mathcal{G}}}_{j+1}( {\mathssf{f}}_j ,{\mathssf{f}}_{j+1}, {\mathssf{s}}^n_{j-2},) \label{eq:Fano1a}
\end{align} such that
\begin{align}
&\Pr(\tilde{{\mathssf{s}}}_j^n \neq {\mathssf{s}}_j^n) \le \Pr(\hat{{\mathssf{s}}}_j^n \neq {\mathssf{s}}_j^n)\\
&\Pr(\tilde{{\mathssf{s}}}_{j+1}^n \neq {\mathssf{s}}_{j+1}^n) \le \Pr(\hat{{\mathssf{s}}}_{j+1}^n \neq {\mathssf{s}}_{j+1}^n)  \label{eq:ErPr}.
\end{align} \hfill$\Box$

Assume that the extra side-informations ${\mathssf{s}}^n_{j-1}$ 
is revealed to the decoder $j$.

Now define the maximum a posteriori probability (MAP) decoder as follow. 
\begin{align}
&\tilde{{\mathssf{s}}}_j^n = {\overline{{\mathcal{G}}}}_{j}([{\mathssf{f}}]_0^j,{\mathssf{s}}_{-1}^n, {\mathssf{s}}^n_{j-1}) \triangleq \underset{{\mathssf{s}}_j^n}{\operatorname{argmax}} \quad   p({\mathssf{s}}_j^n | [{\mathssf{f}}]_0^{j},{\mathssf{s}}_{-1}^n, {\mathssf{s}}^n_{j-1}) \label{eq:MAP1}

\end{align} where we dropped the subscript in conditional probability density for sake of simplicity.




It is known that the MAP decoder is optimal and minimizes the decoding error probability, therefore
\begin{align}
&\Pr(\tilde{{\mathssf{s}}}_j^n \neq {\mathssf{s}}_j^n) \le \Pr(\hat{{\mathssf{s}}}_j^n \neq {\mathssf{s}}_j^n)  \label{eq:ineq1}

\end{align}
Also note that 
\begin{align}
\tilde{{\mathssf{s}}}_j^n = {\overline{{\mathcal{G}}}}_{j}([{\mathssf{f}}]_0^j,{\mathssf{s}}_{-1}^n, {\mathssf{s}}_{j-1}^n)& = \underset{{\mathssf{s}}_j^n}{\operatorname{argmax}} \quad   p({\mathssf{s}}_j^n | [{\mathssf{f}}]_0^{j},{\mathssf{s}}_{-1}^n,{\mathssf{s}}_{j-1}^n) \label{eq:MAPG1O}\\
& =\underset{{\mathssf{s}}_j^n}{\operatorname{argmax}} \quad   p({\mathssf{s}}_j^n | {\mathssf{f}}_{j},{\mathssf{s}}_{j-1}^n) \label{eq:MAPGG1}\\
&\triangleq  \tilde{{\mathcal{G}}}_{j}({\mathssf{f}}_{j},{\mathssf{s}}_{j-1}^n) \label{eq:De1}
\end{align} where \eqref{eq:MAPGG1} follows form the following Markov property. 
\begin{align}
\left([{\mathssf{f}}]_0^{j-1}, {\mathssf{s}}_{-1}^n\right) \rightarrow ({\mathssf{f}}_{j}, {\mathssf{s}}_{j-1}^n) \rightarrow {\mathssf{s}}_{j}^n.
\end{align} 













It can be shown through similar steps that the decoder defined in \eqref{eq:Fano1a} exists with the error probability satisfying \eqref{eq:ErPr}.  
This completes the proof.

The set of all achievable rate-pairs $(R_j, R_{j+1})$ for the problem in Fig.~\ref{fig:zigZag}(a) is identical to the set of all achievable rate-pairs for the problem in Fig.~\ref{fig:zigZag}(b)
where the side information sequence ${\mathssf{s}}_{j-1}^n$ at decoder 1 is replaced by the side information sequence ${\mathssf{s}}_{j+1}^n$.
\label{lem:SI}

The proof of Lemma~\ref{lem:SI} follows by observing that the capacity region for the problem in Fig.~\ref{fig:zigZag}(a) depends on the joint distribution $p({\mathssf{s}}_j, {\mathssf{s}}_{j+1}, {\mathssf{s}}_{j-1},{\mathssf{s}}_{j-B-1})$ only via the {\em marginal}
distributions $p({\mathssf{s}}_j, {\mathssf{s}}_{j-1})$ and $p({\mathssf{s}}_{j+1}, {\mathssf{s}}_j, {\mathssf{s}}_{j-B-1})$.  Indeed the decoding error at decoder $j$ depends on the former whereas the decoding error at decoder ${j+1}$ depends on the latter. When the source is symmetric,  the joint distributions $p({\mathssf{s}}_j, {\mathssf{s}}_{j-1})$ and $p({\mathssf{s}}_j, {\mathssf{s}}_{j+1})$ are identical and thus exchanging ${\mathssf{s}}_{j-1}^n$ with ${\mathssf{s}}_{j+1}^n$ does not change the error probability at decoder $j$ and leaves the functions at all other terminals unchanged. The formal proof is straightforward and will be omitted. 


Thus it suffices to lower bound the achievable sum-rate for the problem in Fig.~\ref{fig:zigZag}(b). First note that 

\begin{align}
nR_{j+1}&= H({\mathssf{f}}_{j+1})\notag\\
&\ge I({\mathssf{f}}_{j+1} ;{\mathssf{s}}_{j+1}^n | {\mathssf{s}}^n_{j-B-1}, {\mathssf{f}}_{j})\notag\\
&=  H({\mathssf{s}}_{j+1}^n|{\mathssf{s}}_{j-B-1}^n, {\mathssf{f}}_{j}) -H({\mathssf{s}}_{j+1}^n|{\mathssf{s}}_{j-B-1}^n, {\mathssf{f}}_{j}, {\mathssf{f}}_{j+1})\notag\\
&\ge H({\mathssf{s}}_{j+1}^n|{\mathssf{s}}_{j-B-1}^n, {\mathssf{f}}_{j}) - n\varepsilon_n\label{eq:sum1}
\end{align}where \eqref{eq:sum1} follows by applying Fano's inequality for decoder $j+1$ in Fig.~\ref{fig:zigZag}(b) since ${\mathssf{s}}_{j+1}^n$ can be recovered from $({\mathssf{s}}_{j-B-1}^n, {\mathssf{f}}_{j}, {\mathssf{f}}_{j+1})$. To bound $R_j$
\begin{align}
&nR_{j}= H({\mathssf{f}}_{j})\notag\\
&\ge I({\mathssf{f}}_{j};{\mathssf{s}}^n_{j}|{\mathssf{s}}_{j-B-1}^n)\nonumber \\
&= H({\mathssf{s}}_{j}^n|{\mathssf{s}}_{j-B-1}^n)\notag - H({\mathssf{s}}_{j}^n|{\mathssf{s}}_{j-B-1}^n, {\mathssf{f}}_{j})\nonumber \\
&\ge nH({\mathssf{s}}_{j}|{\mathssf{s}}_{j-B-1})- H({\mathssf{s}}_{j}^n|{\mathssf{s}}_{j-B-1}^n, {\mathssf{f}}_{j}) \notag\\ &\quad +H({\mathssf{s}}_{j}^n|{\mathssf{s}}_{j-B-1}^n,{\mathssf{s}}_{j+1}^n, {\mathssf{f}}_{j})-n\varepsilon_n\label{eq:FanoApp_Sj}\\
&=nH({\mathssf{s}}_{j}|{\mathssf{s}}_{j-B-1})  - I({\mathssf{s}}_{j}^n; {\mathssf{s}}_{j+1}^n |{\mathssf{s}}_{j-B-1}^n, {\mathssf{f}}_{j})-n\varepsilon_n\nonumber\\
&=nH({\mathssf{s}}_{j}|{\mathssf{s}}_{j-B-1})-H({\mathssf{s}}_{j+1}^n |{\mathssf{s}}_{j-B-1}^n, {\mathssf{f}}_{j}) \notag\\ &\quad + H( {\mathssf{s}}_{j+1}^n |{\mathssf{s}}_{j-B-1}^n,{\mathssf{s}}_{j}^n, {\mathssf{f}}_{j})-n\varepsilon_n\nonumber\\
&=nH({\mathssf{s}}_{j}|{\mathssf{s}}_{j-B-1})-H({\mathssf{s}}_{j+1}^n |{\mathssf{s}}_{j-B-1}^n, {\mathssf{f}}_{j}) \notag\\ &\quad + nH({\mathssf{s}}_{j+1}|{\mathssf{s}}_j) -n\varepsilon_n\label{eq:sum2}
\end{align}
where~\eqref{eq:FanoApp_Sj} follows by applying Fano's inequality for decoder $j$ in Fig.~\ref{fig:zigZag}(b) since ${\mathssf{s}}_j^n$ can be recovered from $({\mathssf{s}}_{j+1}^n, {\mathssf{f}}_j)$ and hence $H({\mathssf{s}}_{j}^n|{\mathssf{s}}_{j-B-1}^n,{\mathssf{s}}_{j+1}^n, {\mathssf{f}}_{j}) \le n\varepsilon_n$ holds and~\eqref{eq:sum2} follows from the Markov relation ${{\mathssf{s}}_{j+1}^n \rightarrow {\mathssf{s}}_j^n \rightarrow ({\mathssf{f}}_j, {\mathssf{s}}_{j-B-1}^n)}$. By summing~\eqref{eq:sum1} and~\eqref{eq:sum2} and using $R_j=R_{j+1}=R$, we have 
\begin{align}
R_{j}+R_{j+1} &\ge H({\mathssf{s}}_{j+1}|{\mathssf{s}}_{j}) + H({\mathssf{s}}_{j}|{\mathssf{s}}_{j-B-1}) \\
&= H({\mathssf{s}}_{j},{\mathssf{s}}_{j+1}|{\mathssf{s}}_{j-B-1})\label{eq:Q2}.
\end{align}
which is equivalent to~\eqref{eq:Rj_lb}.

