\begin{align}
\{{\mathssf{u}}_{0}, {\mathssf{s}}_{-1}\}  \rightarrow  \{[{\mathssf{u}}]_{1}^{t-B}, {\mathssf{s}}_{0}\}  \rightarrow {\mathssf{u}}_{t+1}.
