\label{lem:AchGM}
Consider  random variables $\{{\mathssf{X}}_{0}, {\mathssf{X}}_{1}, {\mathssf{X}}_{2}, {\mathssf{Y}}_{1} , {\mathssf{Y}}_{2}\}$ that are jointly Gaussian, ${\mathssf{X}}_{k} \sim {\mathcal{N}}(0,1), k\in\{0,1,2\}$,  ${\mathssf{X}}_0 \rightarrow {\mathssf{X}}_1 \rightarrow {\mathssf{X}}_2$ and that for $j\in\{1,2\}$ we have: 
\begin{align}
{\mathssf{X}}_{j} &\!= \rho_{j} {\mathssf{X}}_{j-1} + {\mathssf{N}}_{j}, \\
{\mathssf{Y}}_{j} &\!= {\mathssf{X}}_{j} + {\mathssf{Z}}_{j}.
\end{align}
 Assume that ${\mathssf{Z}}_{j} \sim {\mathcal{N}}(0,\sigma^2_{z})$ are independent of all random variables and likewise  ${\mathssf{N}}_{j} \sim {\mathcal{N}}(0,1-\rho^{2}_{j})$ for $j\in\{1,2\}$ are also independent of all random variables.  The structure of correlation is sketched in Fig.~\ref{fig:five}. Then we have that:
\begin{align}
&\sigma^{2}_{{\mathssf{X}}_2}({\mathssf{X}}_0,{\mathssf{Y}}_{2}) \le \sigma^{2}_{{\mathssf{X}}_2}({\mathssf{X}}_0,{\mathssf{Y}}_{1}) \label{eqvar}

\end{align} where $\sigma^{2}_{{\mathssf{X}}_2}({\mathssf{X}}_0,{\mathssf{Y}}_{j})$ denotes the minimum mean square error of estimating ${\mathssf{X}}_2$ from $\{{\mathssf{X}}_0,{\mathssf{Y}}_{j}\}$.

By applying the standard relation for the MMSE estimation error we have (see e.g. \cite{willskyWornel03})
\begin{align}
&\sigma^{2}_{{\mathssf{X}}_2}({\mathssf{X}}_0,{\mathssf{Y}}_{1}) \notag\\
&= E[X_2^2] -\!  \notag\\ 
& \begin{pmatrix}  \! E[X_2 Y_1]\! & \!E[X_2 X_0]\! \end{pmatrix} \begin{pmatrix}
E[Y_1^2]  & E[X_0 Y_1] \\ E[X_0 Y_1] & E[X_0^2]
\end{pmatrix}^{-1} 
\begin{pmatrix}   E[X_2 Y_1] \\ E[X_2 X_0] \end{pmatrix} \\
&=1 - \rho_2^2 \begin{pmatrix}
 1 & \rho_{1} \end{pmatrix}\begin{pmatrix}
1+\sigma^2_{z} & \rho_{1} \\
 \rho_{1} &  1 \end{pmatrix}^{-1}\begin{pmatrix}
1\\
\rho_{1} \end{pmatrix}\\
&= 1- \frac{\rho_{1}^2\rho_{2}^2\sigma^{2}_{z}-\rho_{1}^2\rho_{2}^2+\rho_{2}^2}{1+\sigma^{2}_{z}-\rho^{2}_{1}}\label{eqlem11}
\end{align} 
where we use the fact that $E[X_0^2]=1$, $E[Y_1^2]=1 + \sigma_z^2$,
$E[X_0 Y_1] = \rho_1$, $E[X_2 X_0] = \rho_0 \rho_1$ and $E[X_2 Y_1]= \rho_2$. In a similar fashion it can be shown that:
\begin{align}
\sigma^{2}_{{\mathssf{X}}_2}({\mathssf{X}}_0,{\mathssf{Y}}_{2}) &= 1 -  \begin{pmatrix}
 1 & \rho_{1} \rho_{2} \end{pmatrix}\begin{pmatrix}
1+\sigma^2_{z} & \rho_{1}\rho_{2} \\
 \rho_{1}\rho_{2} &  1 \end{pmatrix}^{-1}\begin{pmatrix}
1\\
\rho_{1}\rho_{2} \end{pmatrix}\\
&= 1- \frac{\rho_{1}^2\rho_{2}^2\sigma^{2}_{z}-\rho_{1}^{2}\rho_{2}^2+1}{1+\sigma^{2}_{z}-\rho^{2}_{1}\rho^{2}_{2}} \label{eqlem22}
\end{align} 
To establish~\eqref{eqvar} we only need to show that, 
\begin{align}
\frac{\rho_{1}^2\rho_{2}^2\sigma^{2}_{z}-\rho_{1}^{2}\rho_{2}^2+1}{1+\sigma^{2}_{z}-\rho^{2}_{1}\rho^{2}_{2}}  \ge  \frac{\rho_{1}^2\rho_{2}^2\sigma^{2}_{z}-\rho_{1}^2\rho_{2}^2+\rho_{2}^2}{1+\sigma^{2}_{z}-\rho^{2}_{1}} \label{eqlem33}
\end{align} It is equivalent to showing 
\begin{align}
\frac{1+\sigma^{2}_{z}-\rho^{2}_{1}}{1+\sigma^{2}_{z}-\rho^{2}_{1}\rho^{2}_{2}} \ge  \frac{\rho_{1}^2\rho_{2}^2\sigma^{2}_{z}-\rho_{1}^2\rho_{2}^2+\rho_{2}^2}{\rho_{1}^2\rho_{2}^2\sigma^{2}_{z}-\rho_{1}^{2}\rho_{2}^2+1}   \label{eqlem44}
\end{align} or equivalently
\begin{align}
1- \frac{\rho^2_{1}(1-\rho^2_{2})}{1+\sigma^{2}_{z}-\rho^{2}_{1}\rho^{2}_{2}} \ge 
1- \frac{1-\rho^2_{2}}{\rho_{1}^2\rho_{2}^2\sigma^{2}_{z}-\rho_{1}^{2}\rho_{2}^2+1}  
\end{align} which is equivalent to showing
\begin{align}
\frac{\rho^2_{1}}{1+\sigma^{2}_{z}-\rho^{2}_{1}\rho^{2}_{2}} \le
\frac{1}{\rho_{1}^2\rho_{2}^2\sigma^{2}_{z}-\rho_{1}^{2}\rho_{2}^2+1}. \label{eq:immediate-verify}
\end{align}
However note that~\eqref{eq:immediate-verify} can be immediately verified since the left hand side
has the numerator smaller than the right hand side and the denominator greater than the right hand side whenever
$\rho_i^2 \in (0,1)$.
This completes the proof.

