\label{lem:AKSuggest}
Consider the Gauss-Markov source model~\eqref{eq:GM-Def} and the test channel in Prop.~\ref{prop:GM-ME}.
For a fixed $t$, $k\in[1, t]$ and a set $\Omega \subseteq [t-k,t]$, consider two sets of random variables ${\mathcal{W}}_1$ and ${\mathcal{W}}_{2}$ each  jointly Gaussian with ${\mathssf{s}}_{t-k}$  such that the following Markov property holds:
\begin{align}
&{\mathcal{W}}_1 \rightarrow {\mathssf{s}}_{t-k} \rightarrow \{{\mathssf{s}}_{t}, {\mathbsf{u}}_{\Omega}\}\\
&{\mathcal{W}}_2 \rightarrow {\mathssf{s}}_{t-k} \rightarrow \{{\mathssf{s}}_{t}, {\mathbsf{u}}_{\Omega}\}
\end{align} If the MMSE error in ${\mathssf{s}}_{t-k}$ satisfies , $\sigma^2_{t-k}({\mathcal{W}}_1)\le \sigma^2_{t-k}({\mathcal{W}}_2)$ then we have
\begin{align}
&h({\mathssf{s}}_{t} | {\mathcal{W}}_1, {\mathbsf{u}}_{\Omega}) \le h({\mathssf{s}}_{t} | {\mathcal{W}}_2, {\mathbsf{u}}_{\Omega}), \qquad \forall \Omega \subseteq [t-k,t] \label{lem:AKs1}\\
&h({\mathssf{u}}_{t} | {\mathcal{W}}_1, {\mathbsf{u}}_{\Omega}) \le h({\mathssf{u}}_{t} | {\mathcal{W}}_2, {\mathbsf{u}}_{\Omega}), \qquad \forall \Omega \subseteq [t-k,t-1] \label{lem:AKs2}.
\end{align}

Since the underlying random variables are jointly Gaussian, we can express the MMSE estimates of ${\mathssf{s}}_{t-k}$ from ${\mathcal{W}}_j$, $j\in\{1,2\}$ as follows (see e.g. \cite{willskyWornel03})
\begin{align}
&\hat{{\mathssf{s}}}_{t-k}({\mathcal{W}}_1) = \alpha_1 {\mathssf{s}}_{t-k} +{\mathssf{e}}_1 \label{eq:AKlem1}\\
&\hat{{\mathssf{s}}}_{t-k}({\mathcal{W}}_2) = \alpha_2 {\mathssf{s}}_{t-k} +{\mathssf{e}}_2 \label{eq:AKlem2}
\end{align} where ${\mathssf{e}}_1 \sim {\mathcal{N}}(0, E_1)$ and ${\mathssf{e}}_2 \sim {\mathcal{N}}(0, E_2)$ are  Gaussian  random variables both independent of ${\mathssf{s}}_{t-k}$. Furthermore the constants in~\eqref{eq:AKlem1} and~\eqref{eq:AKlem2} are given by 
\begin{align}
&\alpha_j = 1-\sigma^2_{t-k}({\mathcal{W}}_j)\\
& E_j = \sigma^2_{t-k}({\mathcal{W}}_j)(1-\sigma^2_{t-k}({\mathcal{W}}_j))
\end{align} for $j=1,2$. To establish~\eqref{lem:AKs1}, we have
\begin{align}
h({\mathssf{s}}_{t} | {\mathcal{W}}_1, {\mathbsf{u}}_{\Omega}) &= h({\mathssf{s}}_{t} | \hat{{\mathssf{s}}}_{t-k}({\mathcal{W}}_1), {\mathbsf{u}}_{\Omega})\label{eq:Ak1}\\
 & = h({\mathssf{s}}_{t} | \alpha_1 {\mathssf{s}}_{t-k} +{\mathssf{e}}_1, {\mathbsf{u}}_{\Omega}) \label{eq:Ak2}\\
 & \le h({\mathssf{s}}_{t} | \alpha_2 {\mathssf{s}}_{t-k} +{\mathssf{e}}_2, {\mathbsf{u}}_{\Omega}) \label{eq:Ak3}\\
 &= h({\mathssf{s}}_{t} | \hat{{\mathssf{s}}}_{t-k}({\mathcal{W}}_2), {\mathbsf{u}}_{\Omega})\label{eq:Ak4}\\
 &= h({\mathssf{s}}_{t} | {\mathcal{W}}_2, {\mathbsf{u}}_{\Omega})\label{eq:Ak5}
\end{align} where \eqref{eq:Ak1} and \eqref{eq:Ak5} follows from the following Markov property. 
\begin{align}
&{\mathcal{W}}_1 \rightarrow \hat{{\mathssf{s}}}_{t-k}({\mathcal{W}}_{1}) \rightarrow \{{\mathssf{s}}_{t}, {\mathssf{u}}_{\Omega}\}\\
&{\mathcal{W}}_2 \rightarrow \hat{{\mathssf{s}}}_{t-k}({\mathcal{W}}_{2}) \rightarrow \{{\mathssf{s}}_{t}, {\mathssf{u}}_{\Omega}\}
\end{align} \eqref{eq:Ak2} and \eqref{eq:Ak4} follows from \eqref{eq:AKlem1} and~\eqref{eq:AKlem2} and \eqref{eq:Ak3} follows from the fact that  $\sigma^2_{t-k}({\mathcal{W}}_1)\le \sigma^2_{t-k}({\mathcal{W}}_2)$ implies that 
\begin{align}
\frac{E_1}{\alpha^2_{1}} \le \frac{E_2}{\alpha^2_{2}}
\end{align} Thus the only difference between~\eqref{eq:Ak2} and~\eqref{eq:Ak3} is that the variance of the independent noise component in the first term is smaller in the former. Clearly we obtain a better estimate of ${\mathssf{s}}_t$ in~\eqref{eq:Ak2}, which justifies the inequality in~\eqref{eq:Ak3}.

Eq.~\eqref{lem:AKs2} can be established as an immediate consequence of~\eqref{lem:AKs1}.
Since the noise ${\mathssf{z}}_{t}$ in the test channel is Gaussian and independent of all other random variables, we have
\begin{align}
\textrm{Var}({\mathssf{u}}_{t}|{\mathcal{W}}_j, {\mathbsf{u}}_{\Omega} ) = \textrm{Var}({\mathssf{s}}_{t}|{\mathcal{W}}_j, {\mathbsf{u}}_{\Omega} ) + \sigma^2_{z}
\end{align} where the notation $\textrm{Var}({\mathssf{a}}|\mathcal{W})$ indicates the noise variance of estimating ${\mathssf{a}}$ from $\mathcal{W}$. As a result, 
\begin{align}
h({\mathssf{u}}_{t} | {\mathcal{W}}_j, {\mathbsf{u}}_{\Omega} ) = \frac{1}{2} \log\left(2^{2h({\mathssf{s}}_{t}|{\mathcal{W}}_j, {\mathbsf{u}}_{\Omega} )}+ 2 \pi e \sigma^2_{z}\right). \label{eq:Ak6}
\end{align} Thus~\eqref{lem:AKs1} immediately imples~\eqref{lem:AKs2}.

\begin{align}
h({\mathssf{s}}_{t} | {\mathcal{W}}_1, {\mathbsf{u}}_{\Omega}) &= h({\mathssf{s}}_{t} | \hat{{\mathssf{s}}}_{t-k}({\mathcal{W}}_1), {\mathbsf{u}}_{\Omega})\label{eq:Ak1}\\
 & = h({\mathssf{s}}_{t} | \alpha_1 {\mathssf{s}}_{t-k} +{\mathssf{e}}_1, {\mathbsf{u}}_{\Omega}) \label{eq:Ak2}\\
 & \le h({\mathssf{s}}_{t} | \alpha_2 {\mathssf{s}}_{t-k} +{\mathssf{e}}_2, {\mathbsf{u}}_{\Omega}) \label{eq:Ak3}\\
 &= h({\mathssf{s}}_{t} | \hat{{\mathssf{s}}}_{t-k}({\mathcal{W}}_2), {\mathbsf{u}}_{\Omega})\label{eq:Ak4}\\
 &= h({\mathssf{s}}_{t} | {\mathcal{W}}_2, {\mathbsf{u}}_{\Omega})\label{eq:Ak5}
\end{align}

