\begin{align}
h({\mathssf{s}}_{b_1}|{\mathssf{u}}_{a_1}, {\mathssf{s}}_{-1}) \ge h({\mathssf{s}}_{b_1}|{\mathssf{u}}_{b_1}, {\mathssf{s}}_{-1}) \label{eq:fori1}
\end{align} Thus~\eqref{ni3sec} holds for $t=b_1$. For any $t > b_1$ we can always express ${\mathssf{s}}_{t} = \rho^{t-b_1}{\mathssf{s}}_{b_1} +\tilde{n}$ where $\tilde{n} \sim {\mathcal{N}}(0,1- \rho^{2(t-b_1)})$ and also we can express ${\mathssf{s}}_{b_1} = \hat{{\mathssf{s}}}_{b_1} ({\mathssf{u}}_{j}, {\mathssf{s}}_{-1}) + {\mathssf{w}}_j$ for $j\in \{a_1 , b_1\}$ where ${\mathssf{w}}_j \sim {\mathcal{N}}(0, \sigma^2_{b_1}({\mathssf{u}}_{j}, {\mathssf{s}}_{-1}))$ is the MMSE estimation error. For $j\in\{a_1, b_1\}$, we have
\begin{align}
{\mathssf{s}}_{t} = \rho^{t-b_1} \hat{{\mathssf{s}}}_{b_1}({\mathssf{u}}_{j}, {\mathssf{s}}_{-1}) + \rho^{t-b_1} {\mathssf{w}}_{j} + \tilde{n}.
\end{align} Then we have
\begin{align}
\sigma^2_t({\mathssf{u}}_{a_1}, {\mathssf{s}}_{-1}) &= \rho^{2(t-b_1)} \sigma^2_{b_1}({\mathssf{u}}_{a_1}, {\mathssf{s}}_{-1}) + 1- \rho^{2(t-b_1)}\\
&\ge \rho^{2(t-b_1)} \sigma^2_{b_1}({\mathssf{u}}_{b_1}, {\mathssf{s}}_{-1}) + 1- \rho^{2(t-b_1)} \label{eq:Asu}\\
&= \sigma^2_t({\mathssf{u}}_{b_1}, {\mathssf{s}}_{-1})\label{eq:Asu1}
\end{align}  where \eqref{eq:Asu} immediately follows from \eqref{eq:fori1}. Thus \eqref{eq:Asu1} establishes \eqref{ni3sec} and the proof of the base case is now complete.

\begin{align}
\lambda_{t}(\Omega_t) &= I({\mathssf{s}}_{t}; {\mathssf{u}}_{t} | {\mathbsf{u}}_{\Omega_t}, {\mathssf{s}}_{-1})\notag\\
&=  h({\mathssf{u}}_{t} | {\mathbsf{u}}_{\Omega_t}, {\mathssf{s}}_{-1})- h( {\mathssf{u}}_{t} | {\mathssf{s}}_{t})\notag\\
& \le h({\mathssf{u}}_{t} | {\mathbsf{u}}_{\Omega^{\star}_t(\theta)}, {\mathssf{s}}_{-1})- h( {\mathssf{u}}_{t} | {\mathssf{s}}_{t})\label{eq:lemp1}\\
& = I({\mathssf{s}}_{t}; {\mathssf{u}}_{t} | {\mathbsf{u}}_{\Omega^{\star}_t(\theta)}, {\mathssf{s}}_{-1}) \notag\\
& = \lambda_{t}(\Omega^{\star}_t(\theta)) \end{align}

For any $t> L+B$, we can write








\begin{align}
 \lambda_{t}(\Omega^{\star}_t) &=  I({\mathssf{s}}_{t};{\mathssf{u}}_{t} | {\mathbsf{u}}_{\Omega^{\star}_{t}}, {\mathssf{s}}_{-1})\\ 
&= I({\mathssf{s}}_{t};{\mathssf{u}}_{t} | {\mathbsf{u}}_{\Omega^{\star}_{t-L-B}}, [{\mathssf{u}}]_{t-L-B+1}^{t-B-1}, {\mathssf{s}}_{-1}) \label{eq:omeg-tilde0}\\
&= I({\mathssf{s}}_{t};{\mathssf{u}}_{t} | \hat{{\mathssf{s}}}_{t-L-B}({\mathbsf{u}}_{\Omega^{\star}_{t-L-B}}, {\mathssf{s}}_{-1}) ,  [{\mathssf{u}}]_{t-L-B+1}^{t-B-1})\label{tilde-1}\\
& \le  I({\mathssf{s}}_{t};{\mathssf{u}}_{t} | \tilde{\alpha} {{\mathssf{s}}}_{t-L-B} + \tilde{{\mathssf{e}}} ,  [{\mathssf{u}}]_{t-L-B+1}^{t-B-1}) \label{tild_exp}\\
& = I({\mathssf{s}}_{t};{\mathssf{u}}_{t} | {{\mathssf{s}}}_{t-L-B} + {{\mathssf{e}}} ,  [{\mathssf{u}}]_{t-L-B+1}^{t-B-1})\notag\\
& = I({\mathssf{s}}_{t};{\mathssf{u}}_{t} | \tilde{{\mathssf{s}}}_{t-L-B} ,  [{\mathssf{u}}]_{t-L-B+1}^{t-B-1})\label{tilde-2}\\
& = R^{+}_{\textrm{GM-ME}}(L,B,D) \label{eq:expre}
\end{align} where~\eqref{eq:omeg-tilde0} follows from the structure of $\Omega_t^\star$ in Lemma~\ref{lem:GM-ME},
~\eqref{tilde-1} follows from the Markov relation\begin{multline}
\{{\mathbsf{u}}_{\Omega^{\star}_{t-L-B}}, {\mathssf{s}}_{-1}\} \rightarrow \{\hat{{\mathssf{s}}}_{t-L-B}({\mathbsf{u}}_{\Omega^{\star}_{t-L-B}}, {\mathssf{s}}_{-1} ), [{\mathssf{u}}]_{t-L-B+1}^{t-B-1} \}\\\rightarrow {\mathssf{s}}_{t} \label{eq:G-ME-Markov-1}
\end{multline}and in \eqref{tild_exp} we introduce ${\tilde{\alpha} = 1-D}$ and ${\tilde{{\mathssf{e}}} \sim {\mathcal{N}}(0, D(1-D))}$.

\begin{align}
 \lambda_{t}(\Omega^{\star}_t) &=  I({\mathssf{s}}_{t};{\mathssf{u}}_{t} | {\mathbsf{u}}_{\Omega^{\star}_{t}}, {\mathssf{s}}_{-1})\\ 
&= I({\mathssf{s}}_{t};{\mathssf{u}}_{t} | {\mathbsf{u}}_{\Omega^{\star}_{t-L-B}}, [{\mathssf{u}}]_{t-L-B+1}^{t-B-1}, {\mathssf{s}}_{-1}) \label{eq:omeg-tilde0}\\
&= I({\mathssf{s}}_{t};{\mathssf{u}}_{t} | \hat{{\mathssf{s}}}_{t-L-B}({\mathbsf{u}}_{\Omega^{\star}_{t-L-B}}, {\mathssf{s}}_{-1}) ,  [{\mathssf{u}}]_{t-L-B+1}^{t-B-1})\label{tilde-1}\\
& \le  I({\mathssf{s}}_{t};{\mathssf{u}}_{t} | \tilde{\alpha} {{\mathssf{s}}}_{t-L-B} + \tilde{{\mathssf{e}}} ,  [{\mathssf{u}}]_{t-L-B+1}^{t-B-1}) \label{tild_exp}\\
& = I({\mathssf{s}}_{t};{\mathssf{u}}_{t} | {{\mathssf{s}}}_{t-L-B} + {{\mathssf{e}}} ,  [{\mathssf{u}}]_{t-L-B+1}^{t-B-1})\notag\\
& = I({\mathssf{s}}_{t};{\mathssf{u}}_{t} | \tilde{{\mathssf{s}}}_{t-L-B} ,  [{\mathssf{u}}]_{t-L-B+1}^{t-B-1})\label{tilde-2}\\
& = R^{+}_{\textrm{GM-ME}}(L,B,D) \label{eq:expre}
\end{align}

This follows from the fact that the estimate $\hat{{\mathssf{s}}}_{t-L-B}({\mathbsf{u}}_{\Omega^{\star}_{t-L-B}}, {\mathssf{s}}_{-1})$ satisfies the average distortion constraint of $D$. In \eqref{tilde-2} we re-normalize the test channel so that ${\mathssf{e}} \sim {\mathcal{N}}(0,D/(1-D))$. Taking the limit of \eqref{eq:expre} when $t\to\infty$, results in \eqref{AppEq1}. Also note that 


\begin{align}
 \gamma_{t}(\Omega^{\star}_t)  &= \sigma^{2}_{t}( {\mathbsf{u}}_{\Omega^{\star}_{t}}, {\mathssf{u}}_{t}, {\mathssf{s}}_{-1}) \notag\\
&=   \sigma^{2}_{t}( {\mathbsf{u}}_{\Omega^{\star}_{t-L-B}}, [{\mathssf{u}}]_{t-L-B+1}^{t-B-1},{\mathssf{u}}_{t}, {\mathssf{s}}_{-1})\notag\\
&=   \sigma^{2}_{t}( \hat{{\mathssf{s}}}_{t-L-B}({\mathbsf{u}}_{\Omega^{\star}_{t-L-B}}, {\mathssf{s}}_{-1}), [{\mathssf{u}}]_{t-L-B+1}^{t-B-1}, {\mathssf{u}}_{t})\label{eq:lem3-7}\\
&\le   \sigma^{2}_{t}( \tilde{\alpha} {{\mathssf{s}}}_{t-L-B} + \tilde{{\mathssf{e}}}, [{\mathssf{u}}]_{t-L-B+1}^{t-B-1}, {\mathssf{u}}_{t}) \label{eq:lem3-8}\\
&=   \sigma^{2}_{t}({{\mathssf{s}}}_{t-L-B} + {{\mathssf{e}}}, [{\mathssf{u}}]_{t-L-B+1}^{t-B-1}, {\mathssf{u}}_{t}) \label{eq:lem3-9}\\
&=   \sigma^{2}_{t}( \tilde{{\mathssf{s}}}_{t-L-B}, [{\mathssf{u}}]_{t-L-B+1}^{t-B-1},{\mathssf{u}}_{t}) \label{eq:Disto}
\end{align} where \eqref{eq:lem3-7} follows from the following Markov property~\eqref{eq:G-ME-Markov-1}
 and \eqref{eq:lem3-8} again follows from the fact that the estimate $\hat{{\mathssf{s}}}_{t-L-B}({\mathbsf{u}}_{\Omega^{\star}_{t-L-B}}, {\mathssf{s}}_{-1})$ satisfies the distortion constraint. All the constants and variables in \eqref{eq:lem3-8} and \eqref{eq:lem3-9} are as defined before. Again, taking the limit of \eqref{eq:Disto} when $t\to \infty$ results in \eqref{AppEq2}.

It follows from standard arguments that~\cite[Chapter 13]{coverThomas} that
\begin{equation}
h({\mathssf{s}}_{t-B-W+i}^n-\{\hat{{\mathssf{s}}}^n_{t-B-W+i}\}_{d_{B+W-i}}) \le \frac{n}{2}\log {2\pi e}{(d_{B+W-i})}. \label{eq:Gauss_Jensen}
\end{equation}
